public class FieldCentrerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("center(\"hi\", 6, '.')", "..hi..", FieldCentrer.center("hi", 6, '.'));
            check("odd padding leans right", "..hi...", FieldCentrer.center("hi", 7, '.'));
            check("single extra pad", "x-", FieldCentrer.center("x", 2, '-'));
            check("already wide enough", "java", FieldCentrer.center("java", 4, '*'));
            check("wider than the field", "javaland", FieldCentrer.center("javaland", 4, '*'));
            check("empty text fills the field", "---", FieldCentrer.center("", 3, '-'));
            check("spaces as padding", "   abc    ", FieldCentrer.center("abc", 10, ' '));
            check("centerBlock two lines", "..ab..\n.cdef.",
                    FieldCentrer.centerBlock(new String[] {"ab", "cdef"}, 6, '.'));
            check("centerBlock of nothing", "", FieldCentrer.centerBlock(new String[] {}, 6, '.'));
        } catch (Throwable t) {
            broke("center", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

