public class FieldCentrer {

    public static String center(String text, int width, char pad) {
        if (text.length() >= width) {
            return text;
        }
        int total = width - text.length();
        int left = total / 2;
        int right = total - left;
        String padding = String.valueOf(pad);
        return padding.repeat(left) + text + padding.repeat(right);
    }

    public static String centerBlock(String[] lines, int width, char pad) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < lines.length; i++) {
            if (i > 0) {
                out.append("\n");
            }
            out.append(center(lines[i], width, pad));
        }
        return out.toString();
    }
}
